messages.content:
Tool response:
Tool: create_cms1500_claim
Description: Create Cms1500 Claim
Parameters:
    {
      "type": "object",
      "properties": {
        "patient_id": {
          "type": "integer",
          "title": "Patient Id",
          "description": "Internal ID of the patient"
        },
        "encounter_date": {
          "type": "string",
          "title": "Encounter Date",
          "description": "Date of the encounter in YYYY-MM-DD format"
        },
        "provider_id": {
          "type": "integer",
          "title": "Provider Id",
          "description": "Internal ID of the provider"
        },
        "cpt_code": {
          "type": "string",
          "title": "Cpt Code",
          "description": "CPT code for the procedure performed"
        },
        "icd10_code": {
          "type": "string",
          "title": "Icd10 Code",
          "description": "ICD-10 code for the diagnosis"
        }
      },
      "required": [
        "patient_id",
        "encounter_date",
        "provider_id",
        "cpt_code",
        "icd10_code"
      ]
    }

Tool response:
Tool: submit_claim
Description: Submit Claim
Parameters:
    {
      "type": "object",
      "properties": {
        "claim_id": {
          "type": "integer",
          "description": "Internal ID of the claim to submit",
          "title": "Claim Id"
        }
      },
      "required": [
        "claim_id"
      ]
    }
